const mod = game.modules.get('draw-steel-combat-tools');
const stealth = mod?.api?.stealth;
const sight = mod?.api?.sight;
const say = (title, body) => ChatMessage.create({
  content: `<div class="dsct-stealth-report"><h3>${title}</h3>${body}</div>`,
  whisper: [game.user.id],
});
if (!stealth || !sight) {
  ui.notifications.error('DSCT stealth api missing. Is the module active, and has the world been reloaded since it was installed?');
  return;
}
const me = canvas.tokens.controlled[0];
if (!me) {
  ui.notifications.warn('Select the token you are testing with first.');
  return;
}
const nameOf = (id) => canvas.tokens.get(id)?.name ?? id;
const list = (names) => names.length ? '<ul><li>' + names.join('</li><li>') + '</li></ul>' : '<p><em>Nobody.</em></p>';

const rows = canvas.tokens.placeables
  .filter(t => t.id !== me.id && t.actor)
  .map(t => {
    const corners = sight.visibleTargetCorners(t, me);
    return `<tr><td>${t.name}</td><td style="text-align:center">${corners}</td>` +
      `<td style="text-align:center">${sight.hasCover(t, me) ? 'yes' : 'no'}</td>` +
      `<td style="text-align:center">${sight.hasSightTo(t, me) ? 'yes' : 'no'}</td>` +
      `<td style="text-align:center">${stealth.isHiddenFrom(me, t) ? 'yes' : 'no'}</td></tr>`;
  });

say(`What everyone can see of ${me.name}`,
  rows.length
    ? '<table><thead><tr><th>Looking at you</th><th>Corners</th><th>You have cover</th><th>Line of effect</th><th>You are hidden</th></tr></thead><tbody>' +
      rows.join('') + '</tbody></table>' +
      '<p><em>Corners is the most of your four they can see from any one of their corners. Two or fewer is cover.</em></p>'
    : '<p><em>Nobody else on the scene.</em></p>');
